function stripComments(source) {
  let out = '', index = 0, quote = null;
  while (index < source.length) {
    const char = source[index], next = source[index + 1];
    if (quote !== null) {
      out += char;
      if (char === '\\') { out += next ?? ''; index += 2; continue; }
      if (char === quote) quote = null;
      index += 1; continue;
    }
    if (char === '"' || char === "'" || char === '`') { quote = char; out += char; index += 1; continue; }
    if (char === '/' && next === '/') { while (index < source.length && source[index] !== '\n') index += 1; continue; }
    if (char === '/' && next === '*') { index += 2; while (index < source.length && !(source[index] === '*' && source[index + 1] === '/')) index += 1; index += 2; continue; }
    out += char; index += 1;
  }
  return out;
}
for (const f of files) {
  const stripped = stripComments(readFileSync(f, 'utf8'));
  const re = /'([^'\n\\]*[\u4e00-\u9fff][^'\n\\]*)'|"([^"\n\\]*[\u4e00-\u9fff][^"\n\\]*)"/g;
  const seen = new Set(); let m; const rows = [];
  while ((m = re.exec(stripped)) !== null) {
    const s = m[1] ?? m[2];
    if (s && !seen.has(s)) { seen.add(s); rows.push(s); }
  }
  console.log('== ' + f + ' (' + rows.length + ') ==');
  for (const r of rows) console.log('  ' + r);
}", "description": "Extract visible Chinese strings from login and 404 pages"}

